J distribution(std::vector<double>v){if(v.empty())return {{"n",0}};std::sort(v.begin(),v.end());auto p=[&](double x){const double k=(v.size()-1)*x;const auto a=std::size_t(k),b=std::min(a+1,v.size()-1);return v[a]+(v[b]-v[a])*(k-a);};return {{"n",v.size()},{"p50",p(.5)},{"p95",p(.95)},{"p99",p(.99)},{"max",v.back()},{"jitter_p95_minus_p5",p(.95)-p(.05)}};}
