J support(const Evaluation&e){J out=J::array();for(std::size_t i=0;i<e.count;++i){const auto&s=e.support[i];out.push_back({{"note",s.note},{"candidate",s.candidate},{"line",s.line},{"hit",{s.hit.x,s.hit.y}},{"terminal",s.terminal},{"body",s.body},{"tail",s.tail},{"accepted",s.accepted},{"own_active",s.active},{"reason",s.reason}});}return out;}
