  const auto&item=frames[k];const auto&i=item.at("index");std::ostringstream relative;relative<<"frames/frame-"<<std::setw(6)<<std::setfill('0')<<k+1<<".png";
  if(item.at("window")!=1||i.at("ordinal")!=k+1||i.at("path")!=relative.str()||i.at("width")!=1280||i.at("height")!=720||i.at("source_rotation")!=1||i.at("clock_domain")!="host_qpc_ns"||i.at("format")!="PNG_RGB24_lossless_unannotated"||i.at("png_sha256")!=item.at("sha256"))throw std::runtime_error("selection continuity/profile/hash binding");
