  Frame f;f.sequence=i.at("source_frame");f.epoch=f.generation=f.geometry_version=1;f.width=1280;f.height=720;f.stride=3840;f.source_rotation=1;f.capture_complete_ns=i.at("capture_complete_ns");f.pixels_ready_ns=i.at("pixels_ready_ns");
